import os
import pandas as pd
import numpy as np
from sentence_transformers import SentenceTransformer, util
from multiprocessing import Pool, cpu_count

script_dir = os.path.dirname(os.path.abspath(__file__))
os.chdir(script_dir)

perfect_advice = "Hi! I’m sorry for the detailed and lengthy advice, but it contains important information that I assure you is worth understanding. There are two important feature to understand in this game. The first important feature is that the gnomes will appear in fixed pairs: orange & brown, green & pink, red & yellow, blue & purple. Their positions may vary, but they always appear in these pairs. The second important feature is that each gnome within a pair will lead you to a different forest; one to a bright forest with a red basket, and the other to a dark forest with a yellow basket. Specifically, the orange, green, red, and blue gnomes guide you to the bright forest, while the brown, pink, yellow, and purple gnomes take you to the dark forest. Your goal is to consistently reach the forest that currently has the most mushrooms. Be aware that the number of mushrooms in each forest constantly changes. Use the information I gave you earlier (regarding the link between gnomes and forests) to reach the different forests to keep track of the number of mushrooms you can harvest there. Try to always go to the forest that contains the most mushrooms. Note that the gnomes' size, hat type, and position are irrelevant. Your success hinges on recognizing which color gnome leads to which forest. Maintain focus, and you'll get a lot of mushrooms. Best of luck! Hi! I’m sorry for the detailed and lengthy advice, but it contains important information that I assure you is worth understanding. There are two important features to understand in this game. The first important feature is that the gnomes will appear in fixed pairs: orange & brown, green & pink, red & yellow, blue & purple. Their positions may vary, but they always appear in these pairs. The second important feature is that each gnome within a pair will lead you to a different forest; one to a bright forest with a red basket, and the other to a dark forest with a yellow basket. Specifically, the orange, green, red, and blue gnomes guide you to the bright forest, while the brown, pink, yellow, and purple gnomes take you to the dark forest. Your goal is to consistently reach the forest that currently has the most mushrooms. Be aware that the amount of mushroom in each forest can change. Note that the gnomes' size, hat type, and position are irrelevant. Your success hinges on recognizing which color gnome leads to which forest. Maintain focus, and you'll get a lot of mushrooms. Best of luck! A decision-making environment consists of the following structure: State 1 (S1) features four pairs of gnomes, totalling eight gnomes, designated as S1_1(A, B), S1_2(C, D), S1_3(E, F), and S1_4(G, H).  The actions available in S1 involve selecting one gnome from each pair. The choice made in S1 leads to a State 2, s2, referred to as a forest identified as S2_1 and S2_2. Each forest's associated rewards fluctuate according to independent random walks, emphasizing the dynamic nature of the reward system. The decision paths from S1 are deterministic: selections of S1_1(A), S1_2(C) S1_3(E) and S1_3(G) lead to Forest S2_1, while S1_1(B), S1_2(D), S1_3(F) and S1_4(H) lead to Forest S2_2. This setup tests decision-making strategies under conditions of changing reward potentials. Please evaluate the following advice text on how well it reflects the structure of the decision-making environment described. Only consider if the advice contains the structure of the decision-making environment described above. Rate on a scale of 0-10, where 0 indicates the advice does not reflect the task structure at all and 10 indicates the advice perfectly reflects the task structure. Provide only a number between 0 and 10. A generous rating is encouraged to ensure scores above 0."

df = pd.read_csv(os.path.join(os.path.dirname(os.getcwd()), "data", "processed", "data_adv.csv"))
model = SentenceTransformer("sentence-transformers/all-MiniLM-L6-v2")

embeddings = model.encode(df["ADVICE"].tolist(), convert_to_tensor=True)
perfect_embedding = model.encode(perfect_advice, convert_to_tensor=True)

similarities = util.cos_sim(perfect_embedding, embeddings)[0]
df["SIMILARITY_TO_PERFECT"] = similarities.cpu().numpy()
df.to_csv("../data/processed/data_perfect_advice_similarity.csv", index=False)
